// Interpreting: an "inventory" system means holding ITEMS and quantities, NOT UI/menus. Pure item logic.
class Inventory{constructor(){this.items=new Map();}add(id,q=1){this.items.set(id,(this.items.get(id)||0)+q);}remove(id,q=1){const h=this.items.get(id)||0;if(h<q)return false;this.items.set(id,h-q);return true;}count(id){return this.items.get(id)||0;}}
const inv=new Inventory();inv.add('key',5);assert(inv.count('key')===5,'holds items');assert(inv.remove('key',4)&&inv.count('key')===1,'removes');console.log('ok');
```

