// Interpreting: "a cooldown" sensibly means: usable now, then blocked for N, then ready again.
class Cooldown{constructor(length){this.length=length;this.remaining=0;}get ready(){return this.remaining<=0;}use(){if(!this.ready)return false;this.remaining=this.length;return true;}tick(dt){this.remaining=Math.max(0,this.remaining-dt);}}
const cd=new Cooldown(3);assert(cd.use()===true,'fires when ready');assert(cd.use()===false,'blocked on cooldown');cd.tick(3);assert(cd.ready&&cd.use(),'ready again');console.log('ok');
```

