// Interpreting: a MINIMAL counter — increment, decrement, reset. Nothing extra.
class Counter{constructor(){this.value=0;}inc(){return ++this.value;}dec(){return --this.value;}reset(){this.value=0;}}
const c=new Counter();for(let i=0;i<9;i++)c.inc();assert(c.value===9,'inc');for(let i=0;i<4;i++)c.dec();assert(c.value===5,'dec');c.reset();assert(c.value===0,'reset');console.log('ok');
```

