// Interpreting: the CORE of a snake game is: move on a grid, GROW when eating, DIE on self/wall collision. Building that logic (no rendering).
class Snake{constructor(w,h){this.w=w;this.h=h;this.body=[{x:2,y:2}];this.dir={x:1,y:0};this.dead=false;}setDir(x,y){this.dir={x,y};}step(food){const head={x:this.body[0].x+this.dir.x,y:this.body[0].y+this.dir.y};if(head.x<0||head.y<0||head.x>=this.w||head.y>=this.h||this.body.some(s=>s.x===head.x&&s.y===head.y)){this.dead=true;return;}this.body.unshift(head);if(food&&head.x===food.x&&head.y===food.y)return true;this.body.pop();return false;}}
const s=new Snake(16,10);assert(s.step({x:3,y:2})===true,'grows on food');assert(s.body.length===2,'grew');const w=new Snake(3,3);w.setDir(1,0);w.step();w.step();assert(w.dead,'dies at wall');console.log('ok');
```

```javascript
function assert(c,m){if(!c)throw new Error('FAIL: '+m);}
// Interpreting: "juicy / game feel" (light ask) means polish PRIMITIVES — easing, a screen-shake offset, a brief hit-stop. Here are the building blocks.
function easeOutQuad(t){return 1-(1-t)*(1-t);}
class Shake{constructor(){this.t=0;this.mag=0;}trigger(mag,dur){this.mag=mag;this.t=dur;}offset(){if(this.t<=0)return{x:0,y:0};this.t--;return{x:(Math.random()*2-1)*this.mag,y:(Math.random()*2-1)*this.mag};}}
assert(easeOutQuad(0)===0&&easeOutQuad(1)===1,'easing endpoints');const s=new Shake();s.trigger(9,4);assert(s.offset().x!==undefined,'shake offset');for(let i=0;i<4;i++)s.offset();assert(s.offset().x===0,'shake ends');console.log('ok');
```

