// Interpreting: "reputation" means STANDING with factions (a value per faction that earns/loses), not reviews/ratings.
class Reputation{constructor(){this.standing=new Map();}change(faction,d){this.standing.set(faction,(this.standing.get(faction)||0)+d);}with(faction){return this.standing.get(faction)||0;}liked(faction){return this.with(faction)>0;}}
const rp=new Reputation();rp.change('syndicate',15);rp.change('syndicate',-4);assert(rp.with('syndicate')===11,'tracks standing');assert(rp.liked('syndicate'),'liked');console.log('ok');
```

