const s=new Snake(15,11);assert(s.step({x:3,y:2})===true,'grows on food');assert(s.body.length===2,'grew');const w=new Snake(3,3);w.setDir(1,0);w.step();w.step();assert(w.dead,'dies at wall');console.log('ok');
```

