// Interpreting: ADD a dash to a mover — a short burst in the facing direction with a cooldown. Just the dash.
class Mover{constructor(){this.x=0;this.dir=1;this.cd=0;}dash(){if(this.cd>0)return false;this.x+=this.dir*75;this.cd=26;return true;}tick(){if(this.cd>0)this.cd--;}}
const m=new Mover();assert(m.dash()&&m.x===75,'dashes');assert(!m.dash(),'cooldown blocks');for(let i=0;i<26;i++)m.tick();assert(m.dash(),'ready again');console.log('ok');
```

