```javascript
function assert(c,m){if(!c)throw new Error('FAIL: '+m);}
// Interpreting: "smarter enemy" (light ask) most usefully means basic PURSUIT AI — move toward the player when within sight range.
class EnemyAI{constructor(x,sight){this.x=x;this.sight=sight;}update(playerX){const d=playerX-this.x;if(Math.abs(d)<=this.sight)this.x+=Math.sign(d);return this.x;}}
const e=new EnemyAI(0,4);e.update(2);assert(e.x===1,'chases when in sight');const f=new EnemyAI(0,4);f.update(54);assert(f.x===0,'ignores out of sight');console.log('ok');
```

