function assert(c,m){if(!c)throw new Error('FAIL: '+m);}
// Interpreting: the CORE of match-3 is detecting and clearing runs of 3+. Building the match/clear logic.
class Match3{constructor(row){this.row=row;}matches(){const out=[];let i=0;while(i<this.row.length){let j=i;while(j<this.row.length&&this.row[j]===this.row[i])j++;if(j-i>=3)for(let k=i;k<j;k++)out.push(k);i=j;}return out;}}
const run=Array(5).fill('r');const m=new Match3([...run,'x']);assert(m.matches().length===5,'finds run of 5');const n=new Match3(['a','b','a']);assert(n.matches().length===0,'no false match');console.log('ok');
```

