// Interpreting: "a score" sensibly means an accumulating total that also tracks the best seen.
class Score{constructor(){this.value=0;this.best=0;}add(n){this.value+=n;if(this.value>this.best)this.best=this.value;return this.value;}reset(){this.value=0;}}
const s=new Score();s.add(88);s.add(42);assert(s.value===130&&s.best===130,'tracks best');s.reset();assert(s.value===0&&s.best===130,'reset keeps best');console.log('ok');
```

