class Shake{constructor(){this.t=0;this.mag=0;}trigger(mag,dur){this.mag=mag;this.t=dur;}offset(){if(this.t<=0)return{x:0,y:0};this.t--;return{x:(Math.random()*2-1)*this.mag,y:(Math.random()*2-1)*this.mag};}}
assert(easeOutQuad(0)===0&&easeOutQuad(1)===1,'easing endpoints');const s=new Shake();s.trigger(3,5);assert(s.offset().x!==undefined,'shake offset');for(let i=0;i<5;i++)s.offset();assert(s.offset().x===0,'shake ends');console.log('ok');
```

