// Interpreting: "health" sensibly means a clamped pool — damage and heal between 0 and max, with a dead flag at 0.
class Health{constructor(max){this.max=max;this.hp=max;}damage(n){this.hp=Math.max(0,this.hp-n);return this.hp;}heal(n){this.hp=Math.min(this.max,this.hp+n);return this.hp;}get dead(){return this.hp<=0;}}
const h=new Health(125);h.damage(110);assert(h.hp===15,'damage');h.heal(9999);assert(h.hp===125,'heal clamps');h.damage(9999);assert(h.dead,'dead at zero');console.log('ok');
