assert(easeOutQuad(0)===0&&easeOutQuad(1)===1,'easing endpoints');const s=new Shake();s.trigger(4,5);assert(s.offset().x!==undefined,'shake offset');for(let i=0;i<5;i++)s.offset();assert(s.offset().x===0,'shake ends');console.log('ok');
```

