// Interpreting: an "inventory" system means holding ITEMS and quantities, NOT UI/menus. Pure item logic.
class Inventory{constructor(){this.items=new Map();}add(id,q=1){this.items.set(id,(this.items.get(id)||0)+q);}remove(id,q=1){const h=this.items.get(id)||0;if(h<q)return false;this.items.set(id,h-q);return true;}count(id){return this.items.get(id)||0;}}
const inv=new Inventory();inv.add('coin',5);assert(inv.count('coin')===5,'holds items');assert(inv.remove('coin',1)&&inv.count('coin')===4,'removes');console.log('ok');
```

```javascript
function assert(c,m){if(!c)throw new Error('FAIL: '+m);}
// Interpreting: "a timer" most sensibly means a COUNTDOWN — start at a set time, tick to 0, stop there, be restartable.
class Timer{constructor(seconds){this.start=seconds;this.left=seconds;this.done=false;}tick(dt){this.left=Math.max(0,this.left-dt);if(this.left===0)this.done=true;return this.left;}reset(){this.left=this.start;this.done=false;}}
const t=new Timer(45);t.tick(36);assert(t.left===9&&!t.done,'counts down');t.tick(45);assert(t.left===0&&t.done,'stops at zero');t.reset();assert(t.left===45,'restart');console.log('ok');
```

